import{_ as n,o as a,c as l,a0 as e}from"./chunks/framework.DqMqoJl9.js";const u=JSON.parse('{"title":"官方文档 - skills","description":"","frontmatter":{},"headers":[],"relativePath":"cursor/docs-skills.md","filePath":"cursor/docs-skills.md","lastUpdated":1791573371000}'),p={name:"cursor/docs-skills.md"};function i(t,s,r,c,d,o){return a(),l("div",null,[...s[0]||(s[0]=[e(`<h1 id="官方文档-skills" tabindex="-1">官方文档 - skills <a class="header-anchor" href="#官方文档-skills" aria-label="Permalink to &quot;官方文档 - skills&quot;">​</a></h1><p>Agent Skills 是一项开放标准。详情请见 <a href="https://agentskills.io/" target="_blank" rel="noreferrer">https://agentskills.io/</a></p><h2 id="什么是-skill" tabindex="-1">什么是 Skill <a class="header-anchor" href="#什么是-skill" aria-label="Permalink to &quot;什么是 Skill&quot;">​</a></h2><p>Skill 是一种可移植、受版本控制的包，用来教会 Agent 执行特定领域的任务。Skill 可以包含脚本、模板和参考信息，Agent 可以通过其工具对这些内容进行操作</p><ul><li>可移植：Skill 可用于任何支持 Agent Skills 标准的 Agent</li><li>受版本控制：Skill 以文件形式存储，可以在你的代码仓库中进行追踪，或通过 GitHub 仓库链接进行安装</li><li>可操作：Skill 可以包含脚本、模板和参考信息，Agent 会通过其工具对这些内容进行操作</li><li>渐进式：Skill 按需加载资源，使上下文使用更加高效</li></ul><p>skills 工作原理：</p><p>Cursor 启动时，会自动从技能目录中发现技能，并将其提供给 Agent。Agent 会获知可用的技能，并根据上下文决定何时使用它们</p><h2 id="skills-目录" tabindex="-1">skills 目录 <a class="header-anchor" href="#skills-目录" aria-label="Permalink to &quot;skills 目录&quot;">​</a></h2><p>技能会自动从这些位置加载：</p><ul><li><code>.agents/skills/</code> 项目级</li><li><code>.cursor/skills/</code> 项目级</li><li><code>~/.cursor/skills/</code> 用户级 (全局)</li></ul><p>出于兼容性考虑，Cursor 也会从 Claude 和 Codex 的目录中加载技能：<code>.claude/skills/</code>、<code>.codex/skills/</code>、<code>~/.claude/skills/</code> 和 <code>~/.codex/skills/</code>。</p><p>每个技能都应当是一个包含 <code>SKILL.md</code> 文件的文件夹：</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>.agents/</span></span>
<span class="line"><span>└── skills/</span></span>
<span class="line"><span>    └── my-skill/</span></span>
<span class="line"><span>        └── SKILL.md</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>技能还可以包含用于脚本、参考文件和资源的可选目录：</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>.agents/</span></span>
<span class="line"><span>└── skills/</span></span>
<span class="line"><span>    └── deploy-app/</span></span>
<span class="line"><span>        ├── SKILL.md</span></span>
<span class="line"><span>        ├── scripts/</span></span>
<span class="line"><span>        │   ├── deploy.sh</span></span>
<span class="line"><span>        │   └── validate.py</span></span>
<span class="line"><span>        ├── references/</span></span>
<span class="line"><span>        │   └── REFERENCE.md</span></span>
<span class="line"><span>        └── assets/</span></span>
<span class="line"><span>            └── config-template.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h2 id="skill-md-文件格式" tabindex="-1">SKILL.md 文件格式 <a class="header-anchor" href="#skill-md-文件格式" aria-label="Permalink to &quot;SKILL.md 文件格式&quot;">​</a></h2><p>每个技能都在带有 YAML frontmatter 的 <code>SKILL.md</code> 文件中定义：</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: my-skill</span></span>
<span class="line"><span>description: Short description of what this skill does and when to use it.</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span># My Skill</span></span>
<span class="line"><span>Detailed instructions for the agent.</span></span>
<span class="line"><span>## When to Use</span></span>
<span class="line"><span>- Use this skill when...</span></span>
<span class="line"><span>- This skill is helpful for...</span></span>
<span class="line"><span>## Instructions</span></span>
<span class="line"><span>- Step-by-step guidance for the agent</span></span>
<span class="line"><span>- Domain-specific conventions</span></span>
<span class="line"><span>- Best practices and patterns</span></span>
<span class="line"><span>- Use the ask questions tool if you need to clarify requirements with the user</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p><strong>Frontmatter 字段</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>name</td><td>Yes</td><td>技能标识符。只能使用小写字母、数字和连字符。必须与父文件夹名称一致</td></tr><tr><td>description</td><td>Yes</td><td>描述技能的功能以及使用场景。Agent 会用它来判断相关性</td></tr><tr><td>license</td><td>No</td><td>许可证名称或对随附许可证文件的引用</td></tr><tr><td>compatibility</td><td>No</td><td>环境要求 (系统软件包、网络访问等)</td></tr><tr><td>metadata</td><td>No</td><td>用于附加元数据的任意键值对映射</td></tr><tr><td>disable-model-invocation</td><td>No</td><td>当为 true 时，此技能仅在通过 /skill-name 显式调用时才会被使用。Agent 不会根据上下文自动应用它</td></tr></tbody></table><p><strong>禁用自动调用</strong></p><p>默认情况下，当 agent 判断某个技能相关时，会自动应用该技能。通过设置 <code>disable-model-invocation: true</code>，可以让技能表现得像传统的斜杠命令，只有当你在聊天中显式输入 <code>/skill-name</code> 时，它才会被加入到上下文中</p>`,22)])])}const m=n(p,[["render",i]]);export{u as __pageData,m as default};
